static const uint8_t font8x16_empty[16] = {0};

const uint8_t *Font8x16_GetGlyph(uint32_t codepoint)
{
  uint32_t lo = 0U;
  uint32_t hi = 162U;
  while (lo < hi) {
    uint32_t mid = lo + ((hi - lo) / 2U);
    uint32_t v = font8x16_table[mid].cp;
    if (v == codepoint) {
      return font8x16_table[mid].rows;
    }
    if (v < codepoint) {
      lo = mid + 1U;
    } else {
      hi = mid;
    }
  }
  return font8x16_empty;
}
